package io.codemyriad.cassini

import io.codemyriad.cassini.core.audio.whistle.WhistleResampler
import io.codemyriad.cassini.test.CiSmoke
import org.junit.Assert.assertEquals
import org.junit.Test
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.security.MessageDigest

/** Run the production scalar arithmetic under ART against independent pinned-desktop C outputs. No audio/model. */
@CiSmoke
class WhistleResamplerDeviceTest {
    @Test
    fun exactDesktopBytesAcrossDecoderChunks() {
        // Generated by whistle/pipeline/reference-fir.py; full source/input provenance is in fir-synthetic.json.
        val cases = listOf(
            4097 to "4216767767f69ac6390060387ee2389f6fffcf8d9a9373e9a8ef17929073b7cf",
            16001 to "61e496865a076e5583b2ee6dfdf967e9ff518ab38bc8e6f79d6ffe788a190051",
        )
        for ((size, expected) in cases) {
            val input = FloatArray(size) { ((it * 7919 + 12345) % 65536 - 32768) / 32768f }
            for (chunk in listOf(47, 8192)) {
                val digest = MessageDigest.getInstance("SHA-256")
                val buffer = ByteBuffer.allocate(4096).order(ByteOrder.LITTLE_ENDIAN)
                var count = 0
                val filter = WhistleResampler(48000) { data, n ->
                    buffer.clear()
                    for (i in 0 until n) buffer.putFloat(data[i])
                    digest.update(buffer.array(), 0, n * 4)
                    count += n
                }
                input.asList().chunked(chunk).forEach { filter.accept(it.toFloatArray()) }
                filter.finish()
                assertEquals((size + 2) / 3, count)
                assertEquals("$size/$chunk", expected, digest.digest().joinToString("") { "%02x".format(it) })
            }
        }
    }
}
